/** Record-create-form graph declaration. */
import { NO_CANVAS, NO_CATALOG, NO_DATA, NO_LIFECYCLE } from "../../graph/types.js";
export const RECORD_CREATE_FORM_RESOURCE_TYPE = "elementum_record_create_form";
/**
 * One immutable create form may be owned by an app or element. Task ownership
 * is not wired into the graph yet. Its
 * provider id is deliberately the owner's id, but Terraform supports the
 * two distinct resource addresses in state, so this resource remains
 * adoptable and participates in pull's zero-write gate.
 */
export const recordCreateFormModule = {
    kind: "record-create-form",
    stream: { role: "streamMember" },
    authoring: { unit: "inline", bag: "recordCreateForm" },
    parents: [
        { parent: "app", child: "record-create-form" },
        { parent: "element", child: "record-create-form" },
    ],
    resource: { shape: "single", resourceType: RECORD_CREATE_FORM_RESOURCE_TYPE, adoptable: true },
    data: NO_DATA,
    lifecycle: NO_LIFECYCLE,
    canvas: NO_CANVAS,
    catalog: NO_CATALOG,
};
